//! Phase 5a — autograd v2 PyTorch parity tests.
//!
//! 26 tests total (13 ops × {backward, forward-mode AD}). Each test
//! loads a PyTorch-generated fixture from `tests/fixtures/`, runs the
//! corresponding v2 op, and compares the produced gradients / output
//! tangent to the PyTorch reference via [`flame_core::parity::ParityHarness`].
//!
//! The fixtures are regenerated by:
//!
//!     python3 tests/fixtures/gen_v2_parity.py
//!
//! at `flame-core/` root, with `torch.manual_seed(42)`. The Python
//! script + the `.safetensors` outputs are all committed under
//! `tests/fixtures/`. The generator script reads as the reference
//! ground-truth definition for every op's parity expectation.
//!
//! ## Tolerance discipline
//!
//! - F32 paths: `min_cos = 0.99999`, `max_abs_ratio = 1e-4`. F32 ops
//!   should be bit-equal to PyTorch up to platform float ordering.
//! - BF16 paths (layer_norm only): `min_cos = 0.999`, `max_abs_ratio =
//!   5e-2`. The BF16 layer_norm backward kernel compounds BF16 noise
//!   through per-row reductions (mean / rstd / dweight via row-sums);
//!   single-row error budget per `BF16_GRAD_DECISION.md`.
//! - View ops (reshape/view/transpose/narrow/squeeze/unsqueeze/permute):
//!   F32 tolerance (no arithmetic; bit-equal).
//!
//! ## Coverage
//!
//! Backward (13):
//!  1. add                7. reshape
//!  2. mul                8. view
//!  3. sum                9. transpose
//!  4. matmul            10. narrow
//!  5. silu              11. squeeze
//!  6. layer_norm        12. unsqueeze
//!                       13. permute
//!
//! Forward-mode AD (13): same 13 ops, with `out_fw` parity instead of
//! `grad_input_*`. The layer_norm JVP formula is the Phase 5a-shipped
//! derivation (see `src/autograd_v2/ops/layer_norm.rs::layer_norm_jvp`).

#![cfg(all(feature = "cuda", feature = "bf16_u16", feature = "autograd_v2"))]

use std::path::PathBuf;
use std::sync::Arc;

use flame_core::autograd_v2::{
    new_meta_ref, AutogradMetaV2, DispatchCtx, Engine, GraphRoot,
};
use flame_core::parity::{ParityHarness, ParityTolerance};
use flame_core::serialization::{load_tensors, SerializationFormat};
use flame_core::{global_cuda_device, DType, Device, Tensor};

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

fn fixtures_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures")
}

fn default_ctx() -> DispatchCtx {
    let dev = Device::from_arc(global_cuda_device().clone());
    DispatchCtx::default_for(dev)
}

/// Attach a fresh `leaf_requires_grad` v2 autograd meta to a tensor
/// loaded from a fixture. Mirrors the helper in
/// `tests/autograd_v2_ops.rs::make_leaf_requires_grad`.
fn as_leaf_requires_grad(mut t: Tensor) -> Tensor {
    let meta = new_meta_ref(AutogradMetaV2::leaf_requires_grad());
    t.set_autograd_meta(Some(meta));
    t
}

/// Strict F32 tolerance — view-style and pure-F32-arithmetic ops.
fn tol_f32_tight() -> ParityTolerance {
    ParityTolerance {
        min_cos: 0.99999,
        max_abs_ratio: 1e-4,
    }
}

/// Relaxed F32 tolerance — arithmetic that compounds rounding (e.g.
/// matmul, sum reductions through the GpuOps F32 path).
fn tol_f32_loose() -> ParityTolerance {
    ParityTolerance {
        min_cos: 0.9999,
        max_abs_ratio: 5e-3,
    }
}

/// BF16 tolerance — layer_norm specifically. BF16 stats kernels
/// compound noise across the per-row reduction.
fn tol_bf16_ln() -> ParityTolerance {
    ParityTolerance {
        min_cos: 0.999,
        max_abs_ratio: 5e-2,
    }
}

/// Compute the param grad for a leaf after `Engine::execute`.
fn take_leaf_grad(t: &Tensor) -> Tensor {
    let meta = t.autograd_meta().expect("leaf has meta");
    let m = meta.lock().unwrap();
    m.grad.as_ref().expect("leaf has accumulated grad").clone()
}

fn load_fixture(name: &str) -> std::collections::HashMap<String, Tensor> {
    let path = fixtures_dir().join(name);
    let device = global_cuda_device().clone();
    load_tensors(&path, device, SerializationFormat::SafeTensors).expect("load fixture")
}

/// Drive the v2 engine end-to-end: backward through `out` with the
/// fixture's `grad_output`. The caller pre-sets the leaves'
/// `requires_grad` meta.
fn run_backward(out: Tensor, grad_output: Tensor, ctx: &DispatchCtx) {
    let root = GraphRoot::new(vec![out]).with_grad_outputs(vec![Some(grad_output)]);
    Engine::new().execute(root, ctx).expect("backward engine execute");
}

/// Take a fixture tensor and ensure it's the dtype the op expects.
fn cast_to(t: &Tensor, dt: DType) -> Tensor {
    if t.dtype() == dt {
        t.clone()
    } else {
        t.to_dtype(dt).expect("dtype cast")
    }
}

/// Open a ParityHarness on a fixture file with a chosen tolerance.
fn harness(fixture: &str, tol: ParityTolerance) -> ParityHarness {
    let path = fixtures_dir().join(fixture);
    let device = global_cuda_device().clone();
    ParityHarness::load(&path, device)
        .expect("load fixture")
        .with_tolerance(tol)
}

// ---------------------------------------------------------------------------
// Backward parity — 13 tests
// ---------------------------------------------------------------------------

#[test]
fn add_backward_matches_pytorch() {
    let f = load_fixture("add_backward.safetensors");
    let a = as_leaf_requires_grad(cast_to(&f["input_0"], DType::F32));
    let b = as_leaf_requires_grad(cast_to(&f["input_1"], DType::F32));
    let g = cast_to(&f["grad_output"], DType::F32);
    let ctx = default_ctx();
    let out = flame_core::autograd_v2::ops::add::add_v2(&a, &b, &ctx).unwrap();
    run_backward(out, g, &ctx);
    let mut h = harness("add_backward.safetensors", tol_f32_tight());
    let _ = h.compare("grad_input_0", &take_leaf_grad(&a)).unwrap();
    let _ = h.compare("grad_input_1", &take_leaf_grad(&b)).unwrap();
    h.assert_clean();
}

