#[test]
fn layer_norm_backward_matches_pytorch() {
    let f = load_fixture("layer_norm_backward.safetensors");
    // LN op is BF16-only.
    let a = as_leaf_requires_grad(cast_to(&f["input_0"], DType::BF16));
    let w = as_leaf_requires_grad(cast_to(&f["input_1"], DType::BF16));
    let b = as_leaf_requires_grad(cast_to(&f["input_2"], DType::BF16));
    let g = cast_to(&f["grad_output"], DType::BF16);
    let ctx = default_ctx();
    let normalized_shape = [w.shape().dims().last().copied().unwrap()];
    let out = flame_core::autograd_v2::ops::layer_norm::layer_norm_v2(
        &a,
        &normalized_shape,
        Some(&w),
        Some(&b),
        1e-5,
        &ctx,
    )
    .unwrap();
    run_backward(out, g, &ctx);
    let mut h = harness("layer_norm_backward.safetensors", tol_bf16_ln());
    let _ = h.compare("grad_input_0", &take_leaf_grad(&a)).unwrap();
    let _ = h.compare("grad_input_1", &take_leaf_grad(&w)).unwrap();
    let _ = h.compare("grad_input_2", &take_leaf_grad(&b)).unwrap();
    h.assert_clean();
}

